def main(raiz):
    d = os.path.join(raiz, 'orbita', 'static', 'i18n')
    for f in sorted(os.listdir(d)):
        if not f.endswith('.json'): continue
        c = f[:-5]
        if c not in T: sys.exit('falta ' + c)
        p = os.path.join(d, f); raw = open(p, encoding='utf-8').read(); j = json.loads(raw)
        for k, v in zip(K, T[c]): j['t'][k] = v
        open(p, 'w', encoding='utf-8').write(json.dumps(j, ensure_ascii=False, indent=1) + ('\n' if raw.endswith('\n') else ''))
    # idioma.js: English and Portuguese, after the «Otros centros de datos» lines
    p = os.path.join(raiz, 'orbita', 'static', 'idioma.js'); s = open(p, encoding='utf-8').read()
    ancla = "    'De compañías con 1 a 4 centros de datos en el mapa, o sin operador conocido.':"
    i = s.index(ancla); i = s.index('\n', i) + 1
    nuevas = ''.join('    %s: [%s, %s],\n' % (json.dumps(k, ensure_ascii=False), json.dumps(e, ensure_ascii=False), json.dumps(pt, ensure_ascii=False)) for k, e, pt in zip(K, T['en'], T['pt']) if json.dumps(k, ensure_ascii=False) + ':' not in s)
    s = s[:i] + nuevas + s[i:]
    open(p, 'w', encoding='utf-8').write(s)
    print('ok', len(T))

if __name__ == '__main__':
    main(sys.argv[1])
